import{_ as e,c as s,o as i,ae as n}from"./chunks/framework.2MVDia4S.js";const g=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md"}'),t={name:"guide/architecture.md"};function o(p,a,l,r,c,d){return i(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>EthBFT delegates networking and Byzantine agreement to CometBFT and delegates Ethereum state transition execution to Geth. Its own responsibility is the small consensus-critical adapter between ABCI and the Engine API.</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant P as Proposer EthBFT</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant PE as Proposer Geth</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant C as CometBFT</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant V as Validator EthBFT</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant VE as Validator Geth</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    P-&gt;&gt;PE: forkchoiceUpdatedV2(attributes)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    P-&gt;&gt;PE: getPayloadV2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    PE--&gt;&gt;P: ExecutionPayload</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    P-&gt;&gt;C: RLP metadata + ordered transactions</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;V: ProcessProposal</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    V-&gt;&gt;VE: newPayloadV2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    VE--&gt;&gt;V: VALID</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    V--&gt;&gt;C: ACCEPT</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;V: FinalizeBlock(decided proposal)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    V-&gt;&gt;VE: forkchoiceUpdatedV2(head=safe=finalized)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    V-&gt;&gt;V: Commit execution app hash and height mapping</span></span></code></pre></div><h2 id="proposal-encoding" tabindex="-1">Proposal encoding <a class="header-anchor" href="#proposal-encoding" aria-label="Permalink to &quot;Proposal encoding&quot;">​</a></h2><p>The first CometBFT proposal item starts with the reserved eight-byte prefix <code>ETHBFT\\x00\\x01</code> and contains canonical RLP execution metadata. Every remaining item is one raw Ethereum transaction. Their byte representation, membership, and order exactly reconstruct <code>ExecutionPayload.transactions</code>.</p><p>Protocol v1 metadata binds:</p><ul><li>protocol and Engine API versions;</li><li>chain ID and CometBFT height;</li><li>previous ABCI app hash;</li><li>parent and proposed EL block hashes;</li><li>state and receipts roots;</li><li>timestamp, randomness, fee recipient, gas, bloom, and base fee; and</li><li>an explicit empty withdrawal list.</li></ul><p>Geth&#39;s <code>ExecutableDataToBlock</code> recomputes the Ethereum header and block hash before the payload is sent to the local Engine API.</p><h2 id="abci-lifecycle" tabindex="-1">ABCI lifecycle <a class="header-anchor" href="#abci-lifecycle" aria-label="Permalink to &quot;ABCI lifecycle&quot;">​</a></h2><h3 id="prepareproposal" tabindex="-1">PrepareProposal <a class="header-anchor" href="#prepareproposal" aria-label="Permalink to &quot;PrepareProposal&quot;">​</a></h3><p>The proposer injects valid candidates into its dedicated Geth txpool, derives payload attributes from CometBFT height/time and committed app state, then asks Geth to build a payload. The resulting payload order becomes consensus data.</p><h3 id="processproposal" tabindex="-1">ProcessProposal <a class="header-anchor" href="#processproposal" aria-label="Permalink to &quot;ProcessProposal&quot;">​</a></h3><p>Every validator performs deterministic checks and calls <code>engine_newPayloadV2</code>. Only <code>VALID</code> is accepted. <code>SYNCING</code>, <code>ACCEPTED</code>, timeouts, malformed envelopes, wrong parents, wrong timestamps, and incorrect block hashes reject the proposal.</p><h3 id="finalizeblock-and-commit" tabindex="-1">FinalizeBlock and Commit <a class="header-anchor" href="#finalizeblock-and-commit" aria-label="Permalink to &quot;FinalizeBlock and Commit&quot;">​</a></h3><p><code>FinalizeBlock</code> revalidates the decided payload and advances EL forkchoice. <code>Commit</code> atomically persists the ABCI app hash and height mapping. Until Commit succeeds, <code>Info</code> continues to report the previous height.</p><h2 id="execution-commitment" tabindex="-1">Execution commitment <a class="header-anchor" href="#execution-commitment" aria-label="Permalink to &quot;Execution commitment&quot;">​</a></h2><p>The app hash is domain-separated and commits to:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>previous app hash</span></span>
<span class="line"><span>chain ID</span></span>
<span class="line"><span>CometBFT height</span></span>
<span class="line"><span>EL parent hash</span></span>
<span class="line"><span>EL block hash</span></span>
<span class="line"><span>state root</span></span>
<span class="line"><span>receipts root</span></span>
<span class="line"><span>transaction root</span></span></code></pre></div><p>Startup verifies that the persisted block remains canonical and restores the committed block as EL head, safe, and finalized.</p><h2 id="code-layout" tabindex="-1">Code layout <a class="header-anchor" href="#code-layout" aria-label="Permalink to &quot;Code layout&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pkg/protocol/proposal.go  canonical execution envelope</span></span>
<span class="line"><span>pkg/bridge/server.go      ABCI lifecycle</span></span>
<span class="line"><span>pkg/bridge/engine.go      proposal building and EL validation</span></span>
<span class="line"><span>pkg/bridge/state.go       commit persistence and reconciliation</span></span>
<span class="line"><span>pkg/ethereum/client.go    authenticated Engine API transport</span></span></code></pre></div>`,21)])])}const E=e(t,[["render",o]]);export{g as __pageData,E as default};
